impl ConformanceRunner {
    /// A runner over the scenarios in `dir` (usually `<repo>/conformance/scenarios`).
    pub fn new(dir: impl Into<PathBuf>) -> Self {
        ConformanceRunner {
            dir: dir.into(),
            capabilities: BTreeSet::new(),
            prefix: DEFAULT_PREFIX.to_owned(),
            vars: Vars::new(),
            handlers: Vec::new(),
            only: None,
        }
    }

    /// Declares capabilities of the target (`write`, `delete`, `versions`, `query`, …).
    pub fn capabilities<I, S>(mut self, caps: I) -> Self
    where
        I: IntoIterator<Item = S>,
        S: Into<String>,
    {
        self.capabilities.extend(caps.into_iter().map(Into::into));
        self
    }

    /// Provider prefix (default `grow-conformance/${run}/`).
    pub fn prefix(mut self, prefix: impl Into<String>) -> Self {
        self.prefix = prefix.into();
        self
    }

    /// Extra variable, e.g. `serviceName`.
    pub fn var(mut self, name: impl Into<String>, value: impl Into<String>) -> Self {
        self.vars.set(name, value);
        self
    }

    /// Registers a category handler (scenarios of other categories are ignored).
    pub fn handler(mut self, handler: impl CategoryHandler + 'static) -> Self {
        self.handlers.push(Arc::new(handler));
        self
    }

    /// Runs only the scenarios with these ids.
    pub fn only<I, S>(mut self, ids: I) -> Self
    where
        I: IntoIterator<Item = S>,
        S: Into<String>,
    {
        self.only = Some(ids.into_iter().map(Into::into).collect());
        self
    }

    /// Loads and runs the scenarios.
    pub async fn run(&self) -> Result<ConformanceReport> {
        let scenarios = load_scenarios(&self.dir)?;
        Ok(self.run_scenarios(&scenarios).await)
    }

    /// Runs already loaded scenarios.
    pub async fn run_scenarios(&self, scenarios: &[Scenario]) -> ConformanceReport {
        let mut report = ConformanceReport::default();
        for scenario in scenarios {
            if self
                .only
                .as_ref()
                .is_some_and(|ids| !ids.contains(&scenario.id))
            {
                continue;
            }
            let Some(handler) = self
                .handlers
                .iter()
                .find(|h| h.category() == scenario.category)
            else {
                continue;
            };
            report
                .results
                .push(self.run_one(handler.as_ref(), scenario).await);
        }
        report
    }

    fn missing(&self, requires: &[String]) -> Vec<String> {
        requires
            .iter()
            .filter(|r| !self.capabilities.contains(*r))
            .cloned()
            .collect()
    }

    async fn run_one(&self, handler: &dyn CategoryHandler, scenario: &Scenario) -> ScenarioResult {
        let started = Instant::now();
        let mut result = ScenarioResult {
            id: scenario.id.clone(),
            category: scenario.category.clone(),
            status: ScenarioStatus::Passed,
            skipped_steps: Vec::new(),
            duration: Duration::ZERO,
        };
        let missing = self.missing(&scenario.requires);
        if !missing.is_empty() {
            result.status =
                ScenarioStatus::Skipped(format!("missing capabilities: {}", missing.join(", ")));
            return result;
        }
        let mut vars = self.vars.clone();
        vars.set("run", run_id());
        let prefix = vars.substitute(&self.prefix);
        vars.set("prefix", prefix);

        let mut session = match handler.open(scenario, &vars).await {
            Ok(s) => s,
            Err(e) => {
                result.status =
                    ScenarioStatus::Failed(format!("setup failed: {} ({})", e, e.code()));
                result.duration = started.elapsed();
                return result;
            }
        };
        for (i, step) in scenario.steps.iter().enumerate() {
            let missing = self.missing(&step.requires);
            if !missing.is_empty() {
                result.skipped_steps.push(format!(
                    "{i}:{} (missing: {})",
                    step.op,
                    missing.join(", ")
                ));
                continue;
            }
            let args = vars.substitute_value(&step.args);
            let outcome = session.run(&step.op, &args, &vars).await;
            let checked = match &step.expect {
                Some(expect) => check_expectation(&vars.substitute_value(expect), &outcome),
                None => match &outcome {
                    Ok(_) => Ok(()),
                    Err(e) => Err(format!("unexpected error {}: {}", e.code(), e)),
                },
            };
            if let Err(msg) = checked {
                result.status = ScenarioStatus::Failed(format!("step {i} ({}): {msg}", step.op));
                break;
            }
            if let (Some(name), Ok(out)) = (&step.save, &outcome) {
                let saved = match &out.value {
                    Value::String(s) => s.clone(),
                    other => other.to_string(),
                };
                vars.set(name.clone(), saved);
            }
        }
        session.close().await;
        result.duration = started.elapsed();
        result
    }
}

/// Random 8-character lowercase id.
pub fn run_id() -> String {
    const ALPHABET: &[u8] = b"abcdefghijklmnopqrstuvwxyz0123456789";
    (0..8)
        .map(|_| ALPHABET[rand::random_range(0..ALPHABET.len())] as char)
        .collect()
}
